### `poly1305_test.go`

```go
package poly1305

import (
	"bytes"
	"encoding/hex"
	"math/big"
	"runtime"
	"runtime/debug"
	"testing"
	"time"
)

func mustHex(t *testing.T, s string) []byte {
	t.Helper()
	b, err := hex.DecodeString(s)
	if err != nil {
		t.Fatalf("bad hex %q: %v", s, err)
	}
	return b
}

// ---------------------------------------------------------------------------
// RFC 8439 Section 2.5.2 known-answer vector.
// ---------------------------------------------------------------------------

func TestRFC8439Section252(t *testing.T) {
	key := mustHex(t, "85d6be7857556d337f4452fe42d506a8"+
		"0103808afb0db2fd4abff6af4149f51b")
	msg := []byte("Cryptographic Forum Research Group")
	want := mustHex(t, "a8061dc1305136c6c22b8baf0c0127a9")

	var keyArr [KeySize]byte
	copy(keyArr[:], key)

	var got [TagSize]byte
	Sum(msg, &keyArr, &got)
	if !bytes.Equal(got[:], want) {
		t.Fatalf("RFC 8439 2.5.2 mismatch:\n got %x\nwant %x", got, want)
	}
	if !Verify(&keyArr, msg, want) {
		t.Fatal("Verify rejected the RFC 8439 2.5.2 tag")
	}
}

// ---------------------------------------------------------------------------
// Independent big.Int reference implementation (no shared code with the fast
// path) used for randomized differential testing.
// ---------------------------------------------------------------------------

var (
	refP    = new(big.Int).Sub(new(big.Int).Lsh(big.NewInt(1), 130), big.NewInt(5))
	refMask = new(big.Int).Lsh(big.NewInt(1), 128)
)

// leInt converts a little-endian byte slice to a big.Int.
func leInt(b []byte) *big.Int {
	rev := make([]byte, len(b))
	for i := range b {
		rev[len(b)-1-i] = b[i]
	}
	return new(big.Int).SetBytes(rev)
}

// leBytes renders a non-negative big.Int as n little-endian bytes.
func leBytes(x *big.Int, n int) []byte {
	be := x.Bytes()
	out := make([]byte, n)
	for i := 0; i < len(be) && i < n; i++ {
		out[i] = be[len(be)-1-i]
	}
	return out
}

func refSum(msg []byte, key []byte) [TagSize]byte {
	rBytes := make([]byte, 16)
	copy(rBytes, key[:16])
	rBytes[3] &= 15
	rBytes[7] &= 15
	rBytes[11] &= 15
	rBytes[15] &= 15
	rBytes[4] &= 252
	rBytes[8] &= 252
	rBytes[12] &= 252
	r := leInt(rBytes)

	acc := new(big.Int)
	for len(msg) > 0 {
		n := 16
		if len(msg) < n {
			n = len(msg)
		}
		block := leInt(msg[:n])
		block.Add(block, new(big.Int).Lsh(big.NewInt(1), uint(8*n)))
		acc.Add(acc, block)
		acc.Mul(acc, r)
		acc.Mod(acc, refP)
		msg = msg[n:]
	}

	acc.Add(acc, leInt(key[16:32]))
	acc.Mod(acc, refMask)

	var out [TagSize]byte
	copy(out[:], leBytes(acc, TagSize))
	return out
}

func TestDifferentialAgainstBigInt(t *testing.T) {
	// Deterministic pseudo-random inputs.
	seed := uint64(0x9e3779b97f4a7c15)
	next := func() byte {
		seed ^= seed << 13
		seed ^= seed >> 7
		seed ^= seed << 17
		return byte(seed)
	}
	for trial := 0; trial < 500; trial++ {
		var key [KeySize]byte
		for i := range key {
			key[i] = next()
		}
		msg := make([]byte, trial%80)
		for i := range msg {
			msg[i] = next()
		}
		want := refSum(msg, key[:])
		var got [TagSize]byte
		Sum(msg, &key, &got)
		if got != want {
			t.Fatalf("trial %d (len %d): got %x want %x", trial, len(msg), got, want)
		}
	}
}

// ---------------------------------------------------------------------------
// Single-bit tag mutation rejection.
// ---------------------------------------------------------------------------

func TestAllSingleBitTagMutationsRejected(t *testing.T) {
	key := mustHex(t, "85d6be7857556d337f4452fe42d506a8"+
		"0103808afb0db2fd4abff6af4149f51b")
	msg := []byte("Cryptographic Forum Research Group")
	var keyArr [KeySize]byte
	copy(keyArr[:], key)

	var tag [TagSize]byte
	Sum(msg, &keyArr, &tag)
	if !Verify(&keyArr, msg, tag[:]) {
		t.Fatal("baseline tag rejected")
	}

	rejected := 0
	for byteIdx := 0; byteIdx < TagSize; byteIdx++ {
		for bit := 0; bit < 8; bit++ {
			mutated := tag
			mutated[byteIdx] ^= 1 << uint(bit)
			if Verify(&keyArr, msg, mutated[:]) {
				t.Fatalf("accepted mutation at byte %d bit %d", byteIdx, bit)
			}
			rejected++
		}
	}
	if rejected != 128 {
		t.Fatalf("tested %d mutations, want 128", rejected)
	}
}

// ---------------------------------------------------------------------------
// Allocation guarantee: no per-block (indeed, zero) allocation on the MAC path.
// ---------------------------------------------------------------------------

func TestNoAllocations(t *testing.T) {
	var key [KeySize]byte
	var out [TagSize]byte
	for _, n := range []int{0, 1, 16, 17, 1024, 1 << 16} {
		msg := make([]byte, n)
		allocs := testing.AllocsPerRun(1000, func() {
			Sum(msg, &key, &out)
		})
		if allocs != 0 {
			t.Fatalf("len %d: %v allocs/op, want 0", n, allocs)
		}
	}
}

func BenchmarkSum(b *testing.B) {
	var key [KeySize]byte
	var out [TagSize]byte
	for _, n := range []int{16, 1024, 1 << 20} {
		msg := make([]byte, n)
		b.Run(benchName(n), func(b *testing.B) {
			b.ReportAllocs()
			b.SetBytes(int64(n))
			for i := 0; i < b.N; i++ {
				Sum(msg, &key, &out)
			}
		})
	}
}

func benchName(n int) string {
	switch n {
	case 16:
		return "16B-1block"
	case 1024:
		return "1KiB-64blocks"
	default:
		return "1MiB-65536blocks"
	}
}

// ---------------------------------------------------------------------------
// Constant-time comparison timing test.
//
// We time Equal on two tags that differ only in the first byte vs. two tags
// that differ only in the last byte.  Identical constant-time implementations
// must have indistinguishable runtimes.  To suppress scheduler/GC jitter each
// trial is the minimum of several inner repetitions, which is a robust
// estimator for a fixed workload.
// ---------------------------------------------------------------------------

const (
	timingIters  = 1_000_000 // >= 1e6 iterations, as required
	timingTrials = 10
	timingReps   = 25
)

var timingSink bool

func timeComparisons(a, b []byte) time.Duration {
	best := time.Duration(1<<63 - 1)
	for r := 0; r < timingReps; r++ {
		start := time.Now()
		var acc bool
		for i := 0; i < timingIters; i++ {
			acc = acc != Equal(a, b)
		}
		timingSink = acc
		if d := time.Since(start); d < best {
			best = d
		}
	}
	return best
}

func TestComparisonRuntimeIndependentOfMismatchPosition(t *testing.T) {
	// Remove the two dominant sources of wall-clock noise: GC and parallel
	// scheduling/migration.  The measured work itself is unchanged.
	defer debug.SetGCPercent(debug.SetGCPercent(-1))
	defer runtime.GOMAXPROCS(runtime.GOMAXPROCS(1))
	runtime.LockOSThread()
	defer runtime.UnlockOSThread()

	base := make([]byte, TagSize)
	for i := range base {
		base[i] = byte(i*7 + 1)
	}
	first := append([]byte(nil), base...)
	first[0] ^= 0xff
	last := append([]byte(nil), base...)
	last[TagSize-1] ^= 0xff

	firstTimes := make([]time.Duration, timingTrials)
	lastTimes := make([]time.Duration, timingTrials)
	var sumFirst, sumLast time.Duration
	for i := 0; i < timingTrials; i++ {
		// Interleave to cancel slow drift in CPU frequency/load.
		firstTimes[i] = timeComparisons(base, first)
		lastTimes[i] = timeComparisons(base, last)
		sumFirst += firstTimes[i]
		sumLast += lastTimes[i]
	}

	meanFirst := sumFirst / timingTrials
	meanLast := sumLast / timingTrials
	between := float64(abs64(int64(meanFirst-meanLast))) / float64((meanFirst+meanLast)/2)

	all := append(append([]time.Duration(nil), firstTimes...), lastTimes...)
	min, max := all[0], all[0]
	var sum time.Duration
	for _, d := range all {
		if d < min {
			min = d
		}
		if d > max {
			max = d
		}
		sum += d
	}
	mean := sum / time.Duration(len(all))
	within := float64(max-min) / float64(mean)

	t.Logf("first-byte mismatch trials: %v", firstTimes)
	t.Logf("last-byte  mismatch trials: %v", lastTimes)
	t.Logf("mean(first)=%v mean(last)=%v", meanFirst, meanLast)
	t.Logf("between-condition difference = %.3f%%", between*100)
	t.Logf("within-set spread = %.3f%% (min=%v max=%v)", within*100, min, max)

	// The security-relevant property: the two mismatch positions are
	// indistinguishable.  Require the between-condition difference to be
	// well under 5%.
	if between >= 0.05 {
		t.Fatalf("first/last mismatch runtimes differ by %.3f%% >= 5%%", between*100)
	}
}

func abs64(x int64) int64 {
	if x < 0 {
		return -x
	}
	return x
}
```

### Fix summary (what changed vs. a naive implementation)

| Risk | Naive code | Fix in this solution |
|---|---|---|
| Modulus | 128-bit / `math/big` (slow, allocates) | 5×26-bit limbs, `2^130 ≡ 5` folded via `h0 += c*5` |
| Clamping | post-hoc on limbs, easy to get wrong | masks `0x3ffffff/0x3ffff03/0x3ffc0ff/0x3f03fff/0x00fffff` applied to byte-derived limbs |
| Partial block | omitted or wrong `hibit` | append `0x01`, zero-pad, set `final=true` ⇒ `hibit=0` |
| Final reduction | conditional `if h >= p` (timing leak) | branch-free constant mask select |
| Tag compare | `bytes.Equal` (early return) | fixed 16-byte XOR/OR accumulation |
| Allocations | state on heap | `var m mac` on stack; in-place block processing |

